// src/aws-config.js
import AWS from 'aws-sdk';

AWS.config.update({
  region: 'YOUR_AWS_REGION', // e.g., 'us-east-1'
  accessKeyId: 'YOUR_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_SECRET_ACCESS_KEY'
});

export const dynamoDb = new AWS.DynamoDB.DocumentClient();
